 #include "utils/perf.h"
 #endif

+#include <array>
+#include <chrono>
+#include <cstdio>
+#include <cstdlib>
+namespace {
+struct LinkTraceTotals {
+  std::array<uint64_t, 11> Ns{};
+  std::array<uint64_t, 11> Counts{};
+  ~LinkTraceTotals() {
+    static const char *Names[] = {"frontend_codegen",
+                                  "mc_finalize",
+                                  "elf_parse",
+                                  "section_scan",
+                                  "symbol_scan",
+                                  "relocation_scan",
+                                  "allocation",
+                                  "copy",
+                                  "object_total_inclusive",
+                                  "patch",
+                                  "protect"};
+    for (unsigned I = 0; I < Ns.size(); ++I)
+      if (Counts[I])
+        std::fprintf(stderr, "LINK_TRACE %s %llu %llu\n", Names[I],
+                     (unsigned long long)Counts[I], (unsigned long long)Ns[I]);
+  }
+};
+thread_local LinkTraceTotals LinkTotals;
+struct LinkTrace {
+  bool Enabled;
+  uint64_t Last;
+  static uint64_t now() {
+    return std::chrono::duration_cast<std::chrono::nanoseconds>(
+               std::chrono::steady_clock::now().time_since_epoch())
+        .count();
+  }
+  LinkTrace()
+      : Enabled(std::getenv("DTVM_LINK_TRACE")), Last(Enabled ? now() : 0) {}
+  void mark(unsigned Phase) {
+    if (!Enabled)
+      return;
+    auto Next = now();
+    LinkTotals.Ns[Phase] += Next - Last;
+    ++LinkTotals.Counts[Phase];
+    Last = Next;
+  }
+};
+} // namespace
 using namespace COMPILER;

 // mprotect need protect by chunks(0x1000) in occulum
@@ -168,7 +215,9 @@ void JITCompilerBase::emitObjectBuffer(CompileContext *Ctx) {
     return;
